import{u as c,C as r,o as a,c as i,j as t,a as o,E as l,k as h,e as u,al as p}from"./chunks/framework.7vp1BMOE.js";const f={key:0},P=JSON.parse('{"title":"PX4-Autopilot v1.18.0 Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"ko/releases/1.18.md","filePath":"ko/releases/1.18.md"}'),g={name:"ko/releases/1.18.md"},A=Object.assign(g,{setup(_){const{site:n}=c();return(m,e)=>{const d=r("Badge"),s=r("Redirect");return a(),i("div",null,[e[1]||(e[1]=t("h1",{id:"px4-autopilot-v1-18-0-release-notes",tabindex:"-1"},[o("PX4-Autopilot v1.18.0 Release Notes "),t("a",{class:"header-anchor",href:"#px4-autopilot-v1-18-0-release-notes","aria-label":'Permalink to "PX4-Autopilot v1.18.0 Release Notes"'},"​")],-1)),l(d,{type:"warning",text:"Beta"}),h(n).title!=="PX4 Guide (main)"?(a(),i("div",f,[e[0]||(e[0]=t("div",{class:"custom-block danger"},[t("p",{class:"custom-block-title"},[o("This page is on a release branch, and hence possibly out of date. "),t("a",{href:"https://docs.px4.io/main/en/releases/1.18"},"See the latest version"),o(".")])],-1)),l(s,{to:"https://docs.px4.io/main/en/releases/1.18"})])):u("",!0),e[2]||(e[2]=p('<p>PX4 v1.18 builds on <a href="./../releases/1.17">PX4 v1.17</a></p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 v1.18 is in beta testing. Update these notes with features that are going to be in <code>v1.18</code>. For new features that aren&#39;t going into v1.18, update <a href="./../releases/main"><code>main</code></a>.</p></div><h2 id="read-before-upgrading" tabindex="-1">Read Before Upgrading <a class="header-anchor" href="#read-before-upgrading" aria-label="Permalink to &quot;Read Before Upgrading&quot;">​</a></h2><p>Please continue reading for <a href="#upgrade-guide">upgrade instructions</a>.</p><h2 id="major-changes" tabindex="-1">Major Changes <a class="header-anchor" href="#major-changes" aria-label="Permalink to &quot;Major Changes&quot;">​</a></h2><ul><li><strong>New Guided Course flight mode (Fixed-Wing).</strong> Holds a constant ground-track bearing, altitude, and airspeed with no manual input, controllable in flight from a GCS via <code>MAV_CMD_GUIDED_CHANGE_HEADING</code>, <code>MAV_CMD_DO_CHANGE_ALTITUDE</code>, and <code>MAV_CMD_DO_CHANGE_SPEED</code>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27156" target="_blank" rel="noreferrer">PX4-Autopilot#27156</a>)</li><li><strong>Software Bill of Materials (SBOM).</strong> Every firmware build now automatically generates an SPDX 2.3 SBOM describing the sources that went into it (opt out with <code>PX4_SBOM_DISABLE=1</code>). (<a href="https://github.com/PX4/PX4-Autopilot/pull/26731" target="_blank" rel="noreferrer">PX4-Autopilot#26731</a>)</li><li><strong>MAVLink signing is now spec-compliant (breaking change).</strong> Signing activates only when a valid key is present on the SD card, <code>SETUP_SIGNING</code> is accepted on any link (not just USB) but rejected while armed, and signing can be disabled with a signed all-zero key. The non-standard <code>MAV_SIGN_CFG</code> parameter was removed, and there is zero CPU/bandwidth overhead when signing is inactive. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26894" target="_blank" rel="noreferrer">PX4-Autopilot#26894</a>)</li><li><strong>Manual control (RC) override reworked (breaking change).</strong> The pilot now regains control based on how fast a stick is moved rather than by how far it is deflected. New <a href="./../advanced_config/parameter_reference#MAN_OVERRIDE_SPD">MAN_OVERRIDE_SPD</a> (normalized stick travel per second, default <code>1</code>, negative to disable) replaces the removed <code>COM_RC_OVERRIDE</code> bitmask and <code>COM_RC_STICK_OV</code> threshold; override now applies uniformly across auto and offboard modes. Existing <code>COM_RC_OVERRIDE=0</code> settings migrate to <code>MAN_OVERRIDE_SPD=-1</code>. Affects multicopters and VTOLs in MC mode. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27041" target="_blank" rel="noreferrer">PX4-Autopilot#27041</a>)</li><li><strong>Runtime EKF2 sensor fusion control over MAVLink.</strong> Fusion sources can now be toggled at runtime (<code>VEHICLE_CMD_ESTIMATOR_SENSOR_ENABLE</code>), a new <a href="./../advanced_config/parameter_reference#EKF2_SENS_EN">EKF2_SENS_EN</a> bitmask (replacing <code>EKF2_EN_BOOT</code>) selects enabled fusion sources, and a new <code>ESTIMATOR_SENSOR_FUSION_STATUS</code> MAVLink stream reports intended and active fusion masks to the GCS. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26739" target="_blank" rel="noreferrer">PX4-Autopilot#26739</a>)</li><li><strong>Per-receiver GPS configuration.</strong> Antenna lever-arm offsets, measurement delay, and device-ID matching moved from single global EKF2 parameters to per-receiver <code>SENS_GPS{0,1}_*</code> sets, enabling correct multi-GPS blending. Removes <code>EKF2_GPS_POS_X/Y/Z</code> and <code>EKF2_GPS_DELAY</code> (auto-migrated). (<a href="https://github.com/PX4/PX4-Autopilot/pull/26634" target="_blank" rel="noreferrer">PX4-Autopilot#26634</a>, <a href="https://github.com/PX4/PX4-Autopilot/pull/26660" target="_blank" rel="noreferrer">PX4-Autopilot#26660</a>)</li><li><strong>UAVCAN node firmware flashing from the SD card.</strong> The UAVCAN server can now flash connected CAN nodes directly from <code>.bin</code> files on the SD card, tracking versions in an <code>FW.db</code> database and reflashing any node whose version does not match. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27043" target="_blank" rel="noreferrer">PX4-Autopilot#27043</a>)</li><li><strong><a href="./../uart/serial_passthrough">Serial Passthrough</a> over MAVLink.</strong> The new <code>serialpassthrough</code> driver lets MAVLink clients read from and write to flight controller serial ports (TEL1/2, GPS1/2, TEL3/4) via <code>SERIAL_CONTROL</code>, so connected devices can be configured without unplugging them from the vehicle. On STM32F7/H7 boards, ESC signal pins can also be written via a software bit-bang UART. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27605" target="_blank" rel="noreferrer">PX4-Autopilot#27605</a>)</li><li><strong>PX4 for ModalAI VOXL 2 ships as a Debian package.</strong> The separate VOXL 2 board variants were merged into a single build, packaged as <code>voxl-px4_*_arm64.deb</code> in CI and published with every PX4 release. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26727" target="_blank" rel="noreferrer">PX4-Autopilot#26727</a>)</li><li><strong>Hardware bench testing (px4bench).</strong> New toolkit (<code>Tools/bench_test/</code>) for automated firmware qualification on a real flight controller over USB: it flashes and verifies the firmware identity, runs boot, communication, storage, parameter-persistence, and serial-loopback checks, and can fly a full SIH auto mission on the FMU itself, writing machine-readable reports with full firmware traceability. See <a href="./../test_and_ci/bench_testing">Hardware Bench Testing</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27823" target="_blank" rel="noreferrer">PX4-Autopilot#27823</a>)</li></ul><h2 id="upgrade-guide" tabindex="-1">Upgrade Guide <a class="header-anchor" href="#upgrade-guide" aria-label="Permalink to &quot;Upgrade Guide&quot;">​</a></h2><p>For users upgrading from v1.17, please take a moment to review the following before flying:</p><ol><li><p><strong>Re-check manual control override behaviour.</strong> The pilot now regains control based on how fast a stick is moved rather than by how far it is deflected, and override applies uniformly across auto and offboard modes. The <code>COM_RC_OVERRIDE</code> bitmask and <code>COM_RC_STICK_OV</code> threshold are replaced by <a href="./../advanced_config/parameter_reference#MAN_OVERRIDE_SPD">MAN_OVERRIDE_SPD</a> (normalized stick travel per second, default <code>1</code>, negative to disable). <code>COM_RC_OVERRIDE=0</code> is migrated to <code>MAN_OVERRIDE_SPD=-1</code>; any other customization must be re-tuned. Affects multicopters and VTOLs in MC mode. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27041" target="_blank" rel="noreferrer">PX4-Autopilot#27041</a>)</p></li><li><p><strong>Re-provision MAVLink signing.</strong> Signing is now spec-compliant: it activates only when a valid key is present on the SD card, and the non-standard <code>MAV_SIGN_CFG</code> parameter has been removed. <code>SETUP_SIGNING</code> is accepted on any link but rejected while armed. If you used signing in v1.17, re-provision the key from your GCS and confirm it supports the standard flow. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26894" target="_blank" rel="noreferrer">PX4-Autopilot#26894</a>)</p></li><li><p><strong>Migrate EKF2 fusion source selection.</strong><code>EKF2_EN_BOOT</code> is replaced by the <a href="./../advanced_config/parameter_reference#EKF2_SENS_EN">EKF2_SENS_EN</a> bitmask selecting which sensor fusion sources are enabled; fusion sources can additionally be toggled at runtime over MAVLink. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26739" target="_blank" rel="noreferrer">PX4-Autopilot#26739</a>)</p></li><li><p><strong>Verify per-receiver GPS configuration.</strong> Antenna lever-arm offsets and measurement delay moved from the global <code>EKF2_GPS_POS_X/Y/Z</code> and <code>EKF2_GPS_DELAY</code> parameters to per-receiver <code>SENS_GPS0_*</code> / <code>SENS_GPS1_*</code> sets matched by device ID. Values are auto-migrated, but multi-GPS setups should verify each receiver&#39;s offsets after upgrading. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26634" target="_blank" rel="noreferrer">PX4-Autopilot#26634</a>, <a href="https://github.com/PX4/PX4-Autopilot/pull/26660" target="_blank" rel="noreferrer">PX4-Autopilot#26660</a>)</p></li><li><p><strong>Review log rotation defaults.</strong> Log rotation is now enabled by default: each log file is capped at <a href="./../advanced_config/parameter_reference#SDLOG_MAX_SIZE">SDLOG_MAX_SIZE</a> (default <code>1024</code> MB) and cleanup keeps at least <code>(100 - SDLOG_ROTATE)%</code> of the disk free (default 10%), running at log start rather than boot. <code>SDLOG_DIRS_MAX</code> is now an orthogonal directory-count cap defaulting to <code>0</code> (disabled) and no longer enforces the old implicit ~300 MB free-space floor; if you relied on that floor, set <a href="./../advanced_config/parameter_reference#SDLOG_ROTATE">SDLOG_ROTATE</a> instead. See <a href="./../dev_log/logging#log-cleanup">Log Cleanup</a>.</p></li><li><p><strong>Update custom logger topic files.</strong><code>etc/logging/logger_topics.txt</code> on the SD card is now appended on top of the selected logging profile instead of replacing the entire topic set. Keep only the extra topics you want in the file. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27462" target="_blank" rel="noreferrer">PX4-Autopilot#27462</a>)</p></li><li><p><strong>Check removed commander parameters.</strong><code>COM_FLT_PROFILE</code>, <code>COM_KILL_DISARM</code>, <code>COM_MOT_TEST_EN</code>, <code>COM_TAKEOFF_ACT</code>, <code>COM_HLDL_REG_T</code>, <code>COM_ARM_SDCARD</code>, <code>COM_IMB_PROP_ACT</code>, <code>COM_OBC_LOSS_T</code>, and <code>COM_LKDOWN_TKO</code> are removed and their previous default behaviour is now fixed (see the removed-parameters table under <a href="#common">Common</a>). In particular, the vehicle now always switches to Hold after takeoff; if you relied on <code>COM_TAKEOFF_ACT</code> to continue into a mission, take off in Mission mode instead.</p></li><li><p><strong>Migrate landing yaw/position nudging.</strong><code>MPC_LAND_RC_HELP</code> is replaced by Bit 1 of <a href="./../advanced_config/parameter_reference#MPC_AUTO_NUDGING">MPC_AUTO_NUDGING</a> (auto-migrated). Bit 0 enables the new yaw nudging in all auto modes. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27691" target="_blank" rel="noreferrer">PX4-Autopilot#27691</a>)</p></li><li><p><strong>Re-tune motor failure detection offsets.</strong><code>MOTFAIL_LOW_OFF</code> and <code>MOTFAIL_HIGH_OFF</code> are replaced by a single <a href="./../advanced_config/parameter_reference#MOTFAIL_OFF">MOTFAIL_OFF</a> (default <code>10</code> A) triggering on absolute current deviation. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26990" target="_blank" rel="noreferrer">PX4-Autopilot#26990</a>)</p></li><li><p><strong>Update GCS/companion software that uses deprecated MAVLink request commands.</strong><code>MAV_CMD_REQUEST_AUTOPILOT_CAPABILITIES</code>, <code>MAV_CMD_REQUEST_PROTOCOL_VERSION</code>, <code>MAV_CMD_GET_HOME_POSITION</code>, <code>MAV_CMD_REQUEST_FLIGHT_INFORMATION</code>, and <code>MAV_CMD_REQUEST_STORAGE_INFORMATION</code> are removed; use <code>MAV_CMD_REQUEST_MESSAGE</code> instead. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27251" target="_blank" rel="noreferrer">PX4-Autopilot#27251</a>, <a href="https://github.com/PX4/PX4-Autopilot/pull/27252" target="_blank" rel="noreferrer">PX4-Autopilot#27252</a>)</p></li><li><p><strong>Update AFBR-S50 startup scripts.</strong> The <code>-r</code> command-line rotation flag is removed; set the mounting orientation via <a href="./../advanced_config/parameter_reference#SENS_AFBR_ROT">SENS_AFBR_ROT</a> instead. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27385" target="_blank" rel="noreferrer">PX4-Autopilot#27385</a>)</p></li></ol><h2 id="hardware-support" tabindex="-1">Hardware Support <a class="header-anchor" href="#hardware-support" aria-label="Permalink to &quot;Hardware Support&quot;">​</a></h2><h3 id="new-flight-controllers" tabindex="-1">New Flight Controllers <a class="header-anchor" href="#new-flight-controllers" aria-label="Permalink to &quot;New Flight Controllers&quot;">​</a></h3><ul><li><a href="./../flight_controller/cuav_x25-mega">CUAV X25-MEGA</a>: STM32H743 autopilot for commercial integration, with triple-redundant heated IMUs (ADIS16607 primary), dual barometers, and an RM3100 compass. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26664" target="_blank" rel="noreferrer">PX4-Autopilot#26664</a>)</li><li><a href="./../flight_controller/cuav_x25-super">CUAV X25-SUPER</a>: STM32H743 autopilot in the same family as the X25-MEGA, with a Murata SCH16T primary IMU, triple-redundant heated IMUs, dual barometers, and an RM3100 compass. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26474" target="_blank" rel="noreferrer">PX4-Autopilot#26474</a>)</li><li><a href="./../flight_controller/corvon_v5">Corvon V5</a>: Pixhawk FMUv5-standard board (STM32F765) with triple IMUs (ICM-20689, ICM-20602, BMI088), IST8310 magnetometer, and MS5611 barometer. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26286" target="_blank" rel="noreferrer">PX4-Autopilot#26286</a>)</li><li><a href="./../flight_controller/corvon_743v2">Corvon 743v2</a>: upgrade of the 743v1 with dual IMUs (ICM-42688P, BMI088), BMP581 barometer, a DJI O4 Air Unit connector, and onboard Bluetooth. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27569" target="_blank" rel="noreferrer">PX4-Autopilot#27569</a>)</li><li><a href="./../flight_controller/aedrox_aedroxh7">AEDROX AEDROXH7</a>: STM32H743-based FPV/racing flight controller (ICM-42688-P IMU, DPS310 barometer, W25N NAND flash, MAX7456 OSD, 8 bidirectional-DShot outputs). (<a href="https://github.com/PX4/PX4-Autopilot/pull/27226" target="_blank" rel="noreferrer">PX4-Autopilot#27226</a>)</li><li><a href="./../flight_controller/cbunmanned_h753-som">CBUnmanned H753-SOM</a>: System-on-Module built around the STM32H753 with dual ICM-42670-P IMUs, designed to be mounted on a vehicle-specific carrier board. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27234" target="_blank" rel="noreferrer">PX4-Autopilot#27234</a>)</li><li><a href="./../flight_controller/3dr_ctrl-n1">3DR Control N1</a>: compact low-profile STM32H743 flight controller (dual IIM-42653 IMUs, AK09940A magnetometer, DPS368 barometer) for use with a carrier board. This board bring-up also introduced the AKM AK09940A magnetometer driver. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27395" target="_blank" rel="noreferrer">PX4-Autopilot#27395</a>)</li><li><strong>ARK FMU-v6s</strong>: a low-cost variant of the ARK V6X (single IIM-42653 IMU, IIS2MDC magnetometer, BMP390 barometer). (<a href="https://github.com/PX4/PX4-Autopilot/pull/26631" target="_blank" rel="noreferrer">PX4-Autopilot#26631</a>)</li><li><a href="./../flight_controller/gearup_airbrainh743">Gear Up AirBrainH743</a>: STM32H743 flight controller with DPS310 barometer, LIS2MDL magnetometer, and 128 MB NAND flash for SD-card-free logging. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26239" target="_blank" rel="noreferrer">PX4-Autopilot#26239</a>)</li><li><a href="./../flight_controller/x-mav_ap-h743r1">X-MAV AP-H743r1</a>: STM32H743 autopilot with a dedicated STM32F103 IO processor, dual IMUs (ICM-42688-P or BMI270 depending on version), and SPL06 barometer. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25967" target="_blank" rel="noreferrer">PX4-Autopilot#25967</a>)</li><li><a href="./../flight_controller/micoair743-lite">MicoAir H743-Lite</a>: compact STM32H743 flight controller with an ICM-45686 IMU and integrated Bluetooth telemetry. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25777" target="_blank" rel="noreferrer">PX4-Autopilot#25777</a>)</li><li><a href="./../flight_controller/svehicle_e2">SVehicle-E2</a>: STM32H753 autopilot with a dedicated STM32F103 IO processor, triple IMUs (BMI088, ICM-42688-P, ICM-20649), and dual ICP-20100 barometers. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25578" target="_blank" rel="noreferrer">PX4-Autopilot#25578</a>)</li></ul><h3 id="new-build-targets-for-existing-hardware" tabindex="-1">New Build Targets for Existing Hardware <a class="header-anchor" href="#new-build-targets-for-existing-hardware" aria-label="Permalink to &quot;New Build Targets for Existing Hardware&quot;">​</a></h3><ul><li>Airship build variant for the FMU-v6x (<code>make px4_fmu-v6x_airship</code>), enabling the airship attitude controller and Cloudship airframe while disabling the multicopter, fixed-wing, and VTOL controllers. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27739" target="_blank" rel="noreferrer">PX4-Autopilot#27739</a>)</li><li>Firmware-release build target for the SAAM saampixv1_1 flight controller.</li></ul><h3 id="new-sensors-peripherals" tabindex="-1">New Sensors &amp; Peripherals <a class="header-anchor" href="#new-sensors-peripherals" aria-label="Permalink to &quot;New Sensors &amp; Peripherals&quot;">​</a></h3><ul><li>ARK MAG DroneCAN magnetometer node. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25822" target="_blank" rel="noreferrer">PX4-Autopilot#25822</a>)</li><li><a href="./../sensor/sbgecom">sbgECom INS</a> driver for SBG Systems inertial navigation sensors. (<a href="https://github.com/PX4/PX4-Autopilot/pull/24137" target="_blank" rel="noreferrer">PX4-Autopilot#24137</a>)</li><li>Sony AS-DT1 <a href="./../sensor/sony_asdt1">distance sensor</a> driver, with mounting orientation configurable via a rotation parameter (enabled on FMU-v6XRT). (<a href="https://github.com/PX4/PX4-Autopilot/pull/27769" target="_blank" rel="noreferrer">PX4-Autopilot#27769</a>)</li><li>Analog Devices ADIS1657x IMU driver. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27239" target="_blank" rel="noreferrer">PX4-Autopilot#27239</a>)</li><li>Analog Devices ADIS1650x IMU driver (ADIS16500/16501/16505/16507 family). (<a href="https://github.com/PX4/PX4-Autopilot/pull/27240" target="_blank" rel="noreferrer">PX4-Autopilot#27240</a>)</li><li>ST LSM6DSV16X IMU driver, enabled as a probe-based alternative IMU on <a href="./../flight_controller/pixhawk6c">Pixhawk 6C</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26951" target="_blank" rel="noreferrer">PX4-Autopilot#26951</a>)</li><li>LSM6DSV 32X and DSK320X variant support in the ST LSM6DSV IMU driver. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27523" target="_blank" rel="noreferrer">PX4-Autopilot#27523</a>)</li><li><a href="./../peripherals/hiwonder_emm">Hiwonder 4-channel encoder motor module</a> driver, enabled via <a href="./../advanced_config/parameter_reference#HIWONDER_EMM_EN">HIWONDER_EMM_EN</a> (started from <code>rc.rover</code>). (<a href="https://github.com/PX4/PX4-Autopilot/pull/27229" target="_blank" rel="noreferrer">PX4-Autopilot#27229</a>)</li><li>TI ADS7128 I2C ADC driver. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26471" target="_blank" rel="noreferrer">PX4-Autopilot#26471</a>)</li><li>AUAV L60D support in the AUAV differential pressure sensor driver. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27219" target="_blank" rel="noreferrer">PX4-Autopilot#27219</a>)</li><li>Infineon DPS368 support in the DPS310 barometer driver, selectable with the <code>-8</code> start flag. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27724" target="_blank" rel="noreferrer">PX4-Autopilot#27724</a>)</li><li><a href="./../sensor/vectornav">VectorNav INS</a> driver: added options to select the IMU output rate and the serial output port. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27318" target="_blank" rel="noreferrer">PX4-Autopilot#27318</a>)</li><li>AFBR-S50 rangefinder: mounting orientation is now set via <a href="./../advanced_config/parameter_reference#SENS_AFBR_ROT">SENS_AFBR_ROT</a> instead of the removed <code>-r</code> command-line flag. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27385" target="_blank" rel="noreferrer">PX4-Autopilot#27385</a>)</li></ul><h3 id="existing-boards-improvements" tabindex="-1">Existing Boards: Improvements <a class="header-anchor" href="#existing-boards-improvements" aria-label="Permalink to &quot;Existing Boards: Improvements&quot;">​</a></h3><ul><li>Accton Godwit GA1: ICM45686 IMU support. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27281" target="_blank" rel="noreferrer">PX4-Autopilot#27281</a>)</li><li>ZeroOne X6 Series V2: TDK IIM42652 IMU and Bosch BMP581 barometer support. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27475" target="_blank" rel="noreferrer">PX4-Autopilot#27475</a>)</li><li>ZeroOne X6: BMM350 compass compatibility. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26870" target="_blank" rel="noreferrer">PX4-Autopilot#26870</a>)</li><li><a href="./../flight_controller/pixhawk6c">Pixhawk 6C</a>: RM3100 fallback for the internal compass. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27299" target="_blank" rel="noreferrer">PX4-Autopilot#27299</a>)</li><li>ModalAI VOXL 2: the separate board variants were merged into a single build, and PX4 for VOXL 2 is now packaged as a Debian package (<code>voxl-px4_*_arm64.deb</code>) that is built in CI and published with every PX4 release. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26727" target="_blank" rel="noreferrer">PX4-Autopilot#26727</a>)</li><li>ModalAI VOXL 2: INA226 and INA228 power monitor support, selectable via the <code>POWER_MANAGER</code> startup option, and the Lightware laser rangefinder driver enabled. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26840" target="_blank" rel="noreferrer">PX4-Autopilot#26840</a>, <a href="https://github.com/PX4/PX4-Autopilot/pull/27620" target="_blank" rel="noreferrer">PX4-Autopilot#27620</a>)</li></ul><h3 id="notable-fixes" tabindex="-1">Notable Fixes <a class="header-anchor" href="#notable-fixes" aria-label="Permalink to &quot;Notable Fixes&quot;">​</a></h3><ul><li>STM32H7 bootloaders rebuilt with the uncorrectable-flash-ECC scrub, preventing a torn parameter-flash write from bricking the board on every subsequent boot. The <code>bl_update</code> command is now included so fielded boards can apply the new bootloader via <a href="./../advanced_config/parameter_reference#SYS_BL_UPDATE">SYS_BL_UPDATE</a> without a debugger. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27715" target="_blank" rel="noreferrer">PX4-Autopilot#27715</a>)</li><li>DShot 3D mode: deadzone inputs now send an explicit motor-stop command instead of spinning the motor at minimum throttle, and the deadband is inclusive on both ends. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26685" target="_blank" rel="noreferrer">PX4-Autopilot#26685</a>)</li><li>Multi-bank Invensense IMUs (IIM-426xx/ICM-42xxx families) no longer get stuck failing to probe until a power cycle when a soft reset leaves a non-zero register bank selected. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27117" target="_blank" rel="noreferrer">PX4-Autopilot#27117</a>)</li><li>SPL06 barometer: fixed an SPI read off-by-one that dropped data bytes. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27074" target="_blank" rel="noreferrer">PX4-Autopilot#27074</a>)</li><li>PAW3902/PAA3905 optical flow sensors now report the actual accumulated integration timespan instead of a hardcoded per-mode interval, fixing flow scaling whenever reads span more than one frame period. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27418" target="_blank" rel="noreferrer">PX4-Autopilot#27418</a>)</li><li>VL53L0X rangefinder: invalid 8.19 m readings are filtered out and measurements now carry a quality field; VL53L1X maps its range status to the quality field. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27214" target="_blank" rel="noreferrer">PX4-Autopilot#27214</a>, <a href="https://github.com/PX4/PX4-Autopilot/pull/27355" target="_blank" rel="noreferrer">PX4-Autopilot#27355</a>, <a href="https://github.com/PX4/PX4-Autopilot/pull/27308" target="_blank" rel="noreferrer">PX4-Autopilot#27308</a>)</li><li>PCA9685 PWM output board now uses the correct internal oscillator frequency, so configured servo PWM rates match the actual output. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27425" target="_blank" rel="noreferrer">PX4-Autopilot#27425</a>)</li><li>MAVLink OpenDroneID Basic ID messages are now forwarded to DroneCAN Remote ID peripherals. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27274" target="_blank" rel="noreferrer">PX4-Autopilot#27274</a>)</li></ul><h2 id="공통" tabindex="-1">공통 <a class="header-anchor" href="#공통" aria-label="Permalink to &quot;공통&quot;">​</a></h2><ul><li><p><a href="./../peripherals/remote_id">Remote ID (Open Drone ID) in-flight failsafe</a>: extended <a href="./../advanced_config/parameter_reference#COM_ARM_ODID">COM_ARM_ODID</a> to also trigger a configurable failsafe action (Return, Land, or Terminate) if the Remote ID heartbeat is lost while airborne. Users previously on <code>COM_ARM_ODID=2</code> retain the same arming behaviour; set to <code>3</code> or higher to enable the in-flight action. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27029" target="_blank" rel="noreferrer">PX4-Autopilot#27029</a>)</p></li><li><p><a href="./../advanced_config/bootloader_update#qgc-bootloader-update-sys-bl-update">QGroundControl Bootloader Update</a> via the <a href="./../advanced_config/parameter_reference#SYS_BL_UPDATE">SYS_BL_UPDATE</a> parameter has been re-enabled after being broken for a number of releases. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25032" target="_blank" rel="noreferrer">PX4-Autopilot#25032: build: romf: fix generation of rc.board_bootloader_upgrade</a>).</p></li><li><p><a href="./../config/manual_control#px4-configuration">Feature: Allow prioritization of manual control inputs based on their instance number in ascending or descending order</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25602" target="_blank" rel="noreferrer">PX4-Autopilot#25602: Ascending and descending manual control input priorities</a>).</p></li><li><p>Quick magnetometer calibration now supports specifying an arbitrary initial heading (<a href="https://github.com/PX4/PX4-Autopilot/pull/24637" target="_blank" rel="noreferrer">PX4-Autopilot#24637</a>)</p></li><li><p>Removed parameters:</p><table tabindex="0"><thead><tr><th>명칭</th><th>참고</th></tr></thead><tbody><tr><td><code>COM_FLT_PROFILE</code></td><td>Unused (<a href="https://github.com/PX4/PX4-Autopilot/pull/26735" target="_blank" rel="noreferrer">PX4-Autopilot#26735</a>)</td></tr><tr><td><code>COM_KILL_DISARM</code></td><td>Autopilot now always disarms if still killed after 5 seconds (previous default). (<a href="https://github.com/PX4/PX4-Autopilot/pull/26736" target="_blank" rel="noreferrer">PX4-Autopilot#26736</a>)</td></tr><tr><td><code>COM_MOT_TEST_EN</code></td><td>Motor tests now always possible (was the default). (<a href="https://github.com/PX4/PX4-Autopilot/pull/26775" target="_blank" rel="noreferrer">PX4-Autopilot#26775</a>)</td></tr><tr><td><code>COM_TAKEOFF_ACT</code></td><td>Vehicle always switches to Hold mode when the takeoff is done. If you want to automatically do a mission, take off in Mission mode. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26808" target="_blank" rel="noreferrer">PX4-Autopilot#26808</a>)</td></tr><tr><td><code>COM_HLDL_REG_T</code></td><td>When a high latency link is regained it&#39;s always considered regained immediately (was the default). (<a href="https://github.com/PX4/PX4-Autopilot/pull/26809" target="_blank" rel="noreferrer">PX4-Autopilot#26809</a>)</td></tr><tr><td><code>COM_ARM_SDCARD</code></td><td>There&#39;s now always a warning when the autopilot SD card is missing (was the default). Boards that don&#39;t have an SD card need to skip the check with a compile time define. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27259" target="_blank" rel="noreferrer">PX4-Autopilot#27259</a>)</td></tr><tr><td><code>COM_IMB_PROP_ACT</code></td><td>There&#39;s now always a warning when imbalanced propellers (high vibration) is detected (was the default). (<a href="https://github.com/PX4/PX4-Autopilot/pull/27260" target="_blank" rel="noreferrer">PX4-Autopilot#27260</a>)</td></tr><tr><td><code>COM_OBC_LOSS_T</code></td><td>Timeout for missing heartbeats from the onboard computer is always 5 seconds (was the default). (<a href="https://github.com/PX4/PX4-Autopilot/pull/27261" target="_blank" rel="noreferrer">PX4-Autopilot#27261</a>)</td></tr><tr><td><code>COM_LKDOWN_TKO</code></td><td>Takeoff failure detection always runs for 3 seconds (was the default). (<a href="https://github.com/PX4/PX4-Autopilot/pull/27262" target="_blank" rel="noreferrer">PX4-Autopilot#27262</a>)</td></tr></tbody></table></li><li><p><a href="./../uart/serial_passthrough">Serial Passthrough (MAVLink SERIAL_CONTROL)</a>: new <code>serialpassthrough</code> driver enables MAVLink clients to read from and write to FC serial ports (TEL1/2, GPS1/2, TEL3/4). On STM32F7/H7 boards, ESC signal pins can also be written via a software bit-bang UART (device IDs 20–27): note that a bridge application is also required, so this functionality is not usable out of the box. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27605" target="_blank" rel="noreferrer">PX4-Autopilot#27605: feat(drivers): implemented serial passthrough</a>).</p></li><li><p>UAVCAN: firmware can now be flashed onto connected CAN nodes directly from the SD card. Place node firmware <code>.bin</code> files at the card root or in <code>/fs/microsd/ufw_staging/</code>; on boot the UAVCAN server migrates them into <code>/fs/microsd/ufw/</code>, tracks them in an <code>FW.db</code> database, and flashes any connected node whose firmware version does not match. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27043" target="_blank" rel="noreferrer">PX4-Autopilot#27043</a>)</p></li></ul><h2 id="제어" tabindex="-1">제어 <a class="header-anchor" href="#제어" aria-label="Permalink to &quot;제어&quot;">​</a></h2><ul><li>Added new flight mode(s): <a href="./../flight_modes_mc/altitude_cruise">Altitude Cruise (MC)</a>, Altitude Cruise (FW). For fixed-wing the mode behaves the same as Altitude mode but you can disable the manual control loss failsafe. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25435" target="_blank" rel="noreferrer">PX4-Autopilot#25435: Add new flight mode: Altitude Cruise</a>).</li><li>Multicopter attitude control gains an optional feed-forward reference model: a 2nd-order critically-damped model smooths the attitude setpoint and feeds its angular-rate derivative onto the rate setpoint, removing the steady-state ramp-tracking lag of the pure-P attitude law. Configured via <a href="./../advanced_config/parameter_reference#MC_REF_W_N">MC_REF_W_N</a>, <a href="./../advanced_config/parameter_reference#MC_REF_FF">MC_REF_FF</a> (default <code>0</code> = disabled), and <a href="./../advanced_config/parameter_reference#MC_REF_FF_MAX">MC_REF_FF_MAX</a>. Shipped disabled by default; <code>MC_REF_FF=0</code> is the exact legacy behavior. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27255" target="_blank" rel="noreferrer">PX4-Autopilot#27255</a>)</li><li>New <a href="./../advanced_config/parameter_reference#COM_FLTMODE_BOOT">COM_FLTMODE_BOOT</a> sets the flight mode the vehicle boots into before any RC input or mode command is received. Default is Hold; Manual, Altitude, Position, Mission, Stabilized, Takeoff, and external modes can also be selected. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27641" target="_blank" rel="noreferrer">PX4-Autopilot#27641</a>)</li><li>Stick inputs are now ignored while an arm or kill gesture is being held: during an arm gesture the throttle and yaw sticks are neutralized, and during a kill gesture all four channels are neutralized, so holding the sticks in the gesture corners no longer feeds spurious commands into the controller.</li><li>New <a href="./../advanced_config/parameter_reference#MPC_Z_ERR_MAX">MPC_Z_ERR_MAX</a> (default <code>1.0</code> m) caps how far the smoothed vertical trajectory may lead the vehicle, the vertical analog of <code>MPC_XY_ERR_MAX</code>. This suppresses altitude overshoots caused by a noisy altitude reference, such as a mission setpoint jittering as the home altitude estimate is refined in flight. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27607" target="_blank" rel="noreferrer">PX4-Autopilot#27607</a>)</li></ul><h2 id="안전-설정" tabindex="-1">안전 설정 <a class="header-anchor" href="#안전-설정" aria-label="Permalink to &quot;안전 설정&quot;">​</a></h2><ul><li>Rotary-wing vehicles now support uncommanded altitude loss detection: if the vehicle descends more than <a href="./../advanced_config/parameter_reference#FD_ALT_LOSS">FD_ALT_LOSS</a> meters below its setpoint in altitude-controlled flight, flight termination (and parachute deployment) is triggered. See <a href="./../config/safety#altitude-loss-trigger">Altitude Loss Trigger</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26837" target="_blank" rel="noreferrer">PX4-Autopilot#26837</a>)</li><li><a href="./../peripherals/parachute">Parachute health failsafe</a>: extended <a href="./../advanced_config/parameter_reference#COM_PARACHUTE">COM_PARACHUTE</a> from a boolean into a configurable arming check and in-flight failsafe action parameter (Warning, Error, Return, or Land). The previously enabled value <code>COM_PARACHUTE=1</code> (Warning) now only warns without preventing arming; use <code>COM_PARACHUTE=2</code> (Error) or higher to prevent arming when the parachute system is missing or unhealthy. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26918" target="_blank" rel="noreferrer">PX4-Autopilot#26918</a>)</li><li><a href="./../config/safety#gnss-check-failsafe">GNSS check failsafe</a>: new failsafe that monitors the number of usable GNSS receivers with a 3D fix and their position consistency. The required number of receivers is set via <a href="./../advanced_config/parameter_reference#SYS_HAS_NUM_GNSS">SYS_HAS_NUM_GNSS</a> and the failsafe action via <a href="./../advanced_config/parameter_reference#COM_GNSSLOSS_ACT">COM_GNSSLOSS_ACT</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26863" target="_blank" rel="noreferrer">PX4-Autopilot#26863</a>)</li><li>New companion computer over-temperature warning: <a href="./../advanced_config/parameter_reference#COM_CC_TEMP_WARN">COM_CC_TEMP_WARN</a> (default <code>80</code> C, set <code>-1</code> to disable) raises a warning when the reported companion computer temperature exceeds the threshold. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27637" target="_blank" rel="noreferrer">PX4-Autopilot#27637</a>)</li><li>New ESC over-temperature warning: <a href="./../advanced_config/parameter_reference#COM_ESC_OT_WARN">COM_ESC_OT_WARN</a> (default <code>90</code> C, set <code>-1</code> to disable) raises a warning when a reported ESC temperature exceeds the threshold. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27626" target="_blank" rel="noreferrer">PX4-Autopilot#27626</a>)</li><li>New actuator group preflight check verifies configured functional actuator groups (torque/thrust/tilt) before arming. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27283" target="_blank" rel="noreferrer">PX4-Autopilot#27283</a>)</li><li>Motor under/over-current failure detection offsets <code>MOTFAIL_LOW_OFF</code> and <code>MOTFAIL_HIGH_OFF</code> are replaced by a single <a href="./../advanced_config/parameter_reference#MOTFAIL_OFF">MOTFAIL_OFF</a> parameter (default <code>10</code> A); the check now triggers on the absolute current deviation. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26990" target="_blank" rel="noreferrer">PX4-Autopilot#26990</a>)</li><li>Rejected missions now report the reason to the GCS (e.g. empty mission, dataman read failure) instead of failing silently. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27254" target="_blank" rel="noreferrer">PX4-Autopilot#27254</a>)</li><li>Arming with <a href="./../advanced_config/parameter_reference#RTL_TYPE">RTL_TYPE</a> set to <code>5</code> (safe points only) no longer requires a rally point to be uploaded: the vehicle falls back to returning to the home position when no rally point is defined. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27773" target="_blank" rel="noreferrer">PX4-Autopilot#27773</a>)</li><li>GCS connection-loss failsafe no longer triggers flight termination while the vehicle is disarmed, preventing a termination state from latching before or at arming after a ground station link loss. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26820" target="_blank" rel="noreferrer">PX4-Autopilot#26820</a>)</li><li>New <a href="./../advanced_config/parameter_reference#NAV_RCL_ACT">NAV_RCL_ACT</a> option <code>7</code> (Hold without failsafe): on manual control (RC) loss the vehicle holds position but does not enter a failsafe state, so an external mode or offboard controller can keep commanding it. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27792" target="_blank" rel="noreferrer">PX4-Autopilot#27792</a>)</li><li>Control allocator now stops the motors when it receives a NaN thrust setpoint, instead of forwarding invalid values to the ESCs. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26494" target="_blank" rel="noreferrer">PX4-Autopilot#26494</a>)</li></ul><h2 id="estimation" tabindex="-1">Estimation <a class="header-anchor" href="#estimation" aria-label="Permalink to &quot;Estimation&quot;">​</a></h2><ul><li>Added <a href="./../advanced_config/parameter_reference#EKF2_POS_LOCK">EKF2_POS_LOCK</a> to force constant position fusion while landed, useful for vehicles relying on dead-reckoning sensors (airspeed, optical flow) that provide no aiding on the ground.</li><li>EKF2 fusion sources can now be toggled at runtime over MAVLink (<code>VEHICLE_CMD_ESTIMATOR_SENSOR_ENABLE</code>), and the new <a href="./../advanced_config/parameter_reference#EKF2_SENS_EN">EKF2_SENS_EN</a> bitmask (replacing <code>EKF2_EN_BOOT</code>) selects which sensor fusion sources are enabled. A new <code>ESTIMATOR_SENSOR_FUSION_STATUS</code> MAVLink stream reports the intended and active fusion source bitmasks to the GCS. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26739" target="_blank" rel="noreferrer">PX4-Autopilot#26739</a>)</li><li>EKF2 now uses latitude-dependent normal gravity (Somigliana model) in the state and output predictor instead of a fixed 9.80665 m/s^2, removing a ~0.5% error that fed directly into the vertical-velocity prediction. Before a global latitude is known it stays at the constant value, preserving prior behavior. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27602" target="_blank" rel="noreferrer">PX4-Autopilot#27602</a>)</li><li>EKF2 now limits the maximum heading change rate from magnetometer fusion to prevent rapid convergence to a wrong heading when heading variance is high. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27551" target="_blank" rel="noreferrer">PX4-Autopilot#27551</a>)</li><li>EKF2 adds ranging beacon (range-only) fusion support, with a MAVLink <code>RANGING_BEACON</code> parser and new parameters <a href="./../advanced_config/parameter_reference#EKF2_RNGBC_CTRL">EKF2_RNGBC_CTRL</a>, <a href="./../advanced_config/parameter_reference#EKF2_RNGBC_DELAY">EKF2_RNGBC_DELAY</a>, <a href="./../advanced_config/parameter_reference#EKF2_RNGBC_GATE">EKF2_RNGBC_GATE</a>, and <a href="./../advanced_config/parameter_reference#EKF2_RNGBC_NOISE">EKF2_RNGBC_NOISE</a>. Beacon range is fused horizontally only (no altitude correction). (<a href="https://github.com/PX4/PX4-Autopilot/pull/26772" target="_blank" rel="noreferrer">PX4-Autopilot#26772</a>)</li><li>GPS antenna position offsets are now configured per receiver via <a href="./../advanced_config/parameter_reference#SENS_GPS0_OFFX">SENS_GPS0_OFFX</a>/<code>_OFFY</code>/<code>_OFFZ</code> (and the <code>SENS_GPS1_*</code> set), matched to a physical receiver by device ID (<a href="./../advanced_config/parameter_reference#SENS_GPS0_ID">SENS_GPS0_ID</a>/<code>SENS_GPS1_ID</code>), replacing the single <code>EKF2_GPS_POS_X/Y/Z</code> set. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26634" target="_blank" rel="noreferrer">PX4-Autopilot#26634</a>)</li><li>GPS measurement delay is now configured per receiver via <a href="./../advanced_config/parameter_reference#SENS_GPS0_DELAY">SENS_GPS0_DELAY</a> and <a href="./../advanced_config/parameter_reference#SENS_GPS1_DELAY">SENS_GPS1_DELAY</a>, replacing <code>EKF2_GPS_DELAY</code> (automatically migrated). The delay is applied before receiver blending; PPS time correction, when active, takes priority. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26660" target="_blank" rel="noreferrer">PX4-Autopilot#26660</a>)</li><li>PPS time synchronization can now select which GPS receiver to correlate against by device ID via the new <a href="./../advanced_config/parameter_reference#PPS_CAP_GPS_ID">PPS_CAP_GPS_ID</a> parameter (reboot required), avoiding dependence on uORB instance ordering in multi-GPS setups. See <a href="./../advanced/pps_time_sync">PPS Time Synchronization</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26719" target="_blank" rel="noreferrer">PX4-Autopilot#26719</a>)</li><li>DroneCAN GNSS receivers can now provide UTC-coherent timestamps: a new leaky-min clock-offset estimator maps a node&#39;s PPS-anchored <code>Fix2.timestamp</code> into the flight controller&#39;s HRT and subtracts the node&#39;s processing delay. Nodes that do not provide a valid UTC timestamp fall back to the <code>SENS_GPS*_DELAY</code> path. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27427" target="_blank" rel="noreferrer">PX4-Autopilot#27427</a>)</li><li>EKF2 can now use GNSS height as the height reference when GNSS is in dead-reckoning mode, provided it can start without requiring a reset. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27766" target="_blank" rel="noreferrer">PX4-Autopilot#27766</a>)</li><li>EKF2 now counts NED-frame external vision velocity fusion as a horizontal (NE) aiding source (and only counts vision position when it is in the NED frame), so vehicles aided only by vision velocity are no longer treated as dead-reckoning. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27538" target="_blank" rel="noreferrer">PX4-Autopilot#27538</a>)</li></ul><h2 id="rc" tabindex="-1">RC <a class="header-anchor" href="#rc" aria-label="Permalink to &quot;RC&quot;">​</a></h2><ul><li>Parse ELRS Status and Link Statistics TX messages in the CRSF parser.</li><li>Manual control (RC) override reworked: the pilot now regains control based on how fast a stick is moved rather than by how far it is deflected, so a statically-held or trimmed-off stick can no longer trigger an unwanted takeover. New <a href="./../advanced_config/parameter_reference#MAN_OVERRIDE_SPD">MAN_OVERRIDE_SPD</a> (normalized stick travel per second, default <code>1</code>, negative to disable) replaces the removed <code>COM_RC_OVERRIDE</code> bitmask and <code>COM_RC_STICK_OV</code> threshold; override now applies uniformly across auto and offboard modes. Existing <code>COM_RC_OVERRIDE=0</code> settings are migrated to <code>MAN_OVERRIDE_SPD=-1</code> on import. Only affects multicopters and VTOLs in MC mode. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27041" target="_blank" rel="noreferrer">PX4-Autopilot#27041</a>)</li><li>CRSF receivers can now be put into bind mode from QGroundControl or the NSH console via <code>MAV_CMD_START_RX_PAIR</code>; the driver sends the CRSF bind frame over UART and rejects binding while armed or on singlewire setups. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26790" target="_blank" rel="noreferrer">PX4-Autopilot#26790</a>)</li></ul><h2 id="vehicle-specific" tabindex="-1">Vehicle-Specific <a class="header-anchor" href="#vehicle-specific" aria-label="Permalink to &quot;Vehicle-Specific&quot;">​</a></h2><h3 id="multi-rotor" tabindex="-1">Multi-Rotor <a class="header-anchor" href="#multi-rotor" aria-label="Permalink to &quot;Multi-Rotor&quot;">​</a></h3><ul><li><p>Removed parameters:</p><table tabindex="0"><thead><tr><th>명칭</th><th>참고</th></tr></thead><tbody><tr><td><code>MPC_LAND_RC_HELP</code></td><td>Replaced by Bit 1 of <a href="./../advanced_config/parameter_reference#MPC_AUTO_NUDGING">MPC_AUTO_NUDGING</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27691" target="_blank" rel="noreferrer">PX4-Autopilot#27691</a>)</td></tr></tbody></table></li><li><p>Yaw stick nudging in auto modes (<a href="./../advanced_config/parameter_reference#MPC_AUTO_NUDGING">MPC_AUTO_NUDGING</a>). Bit 0 lets the yaw stick rotate vehicle heading during any auto mode (mission, RTL, hold, landing, takeoff) without switching modes. The heading is held when the stick is released and cleared on a flight mode switch. Requires stick override to be disabled (<a href="./../advanced_config/parameter_reference#MAN_OVERRIDE_SPD">MAN_OVERRIDE_SPD</a> = -1). (<a href="https://github.com/PX4/PX4-Autopilot/pull/27691" target="_blank" rel="noreferrer">PX4-Autopilot#27691</a>)</p></li></ul><h3 id="수직이착륙기-vtol" tabindex="-1">수직이착륙기(VTOL) <a class="header-anchor" href="#수직이착륙기-vtol" aria-label="Permalink to &quot;수직이착륙기(VTOL)&quot;">​</a></h3><ul><li><a href="./../flight_modes_vtol/return#vtol-rally-point-approach-loiters">Return mode VTOL Rally Point Approach Loiters</a>: VTOLs returning in fixed-wing mode can now use the approach loiter associated with the selected home/rally landing location (instead of home) to choose the most wind-aligned valid approach (if several are defined). (<a href="https://github.com/PX4/PX4-Autopilot/pull/27004" target="_blank" rel="noreferrer">PX4-Autopilot#27004: fix(navigator): rtl compute wind angle to select best land approach based on rally point location instead of home location</a>)</li></ul><h3 id="fixed-wing" tabindex="-1">Fixed-wing <a class="header-anchor" href="#fixed-wing" aria-label="Permalink to &quot;Fixed-wing&quot;">​</a></h3><ul><li>New <a href="./../flight_modes_fw/guided_course">Guided Course mode</a>: maintains a constant ground-track bearing, altitude, and airspeed with no manual stick input. Activated over MAVLink and accepts in-flight updates via <code>MAV_CMD_GUIDED_CHANGE_HEADING</code> (course), <code>MAV_CMD_DO_CHANGE_ALTITUDE</code> (altitude), and <code>MAV_CMD_DO_CHANGE_SPEED</code> (airspeed). (<a href="https://github.com/PX4/PX4-Autopilot/pull/27156" target="_blank" rel="noreferrer">PX4-Autopilot#27156</a>)</li><li>Rate feed-forward parameters <a href="./../advanced_config/parameter_reference#FW_RR_FF">FW_RR_FF</a>, <a href="./../advanced_config/parameter_reference#FW_PR_FF">FW_PR_FF</a>, and <a href="./../advanced_config/parameter_reference#FW_YR_FF">FW_YR_FF</a> now accept negative values (min lowered from <code>0</code> to <code>-10</code>). Negative values reduce setpoint-tracking aggressiveness while preserving disturbance rejection and are scaled quadratically with airspeed, whereas positive values compensate aerodynamic damping and scale linearly. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27736" target="_blank" rel="noreferrer">PX4-Autopilot#27736</a>)</li><li>New <a href="./../advanced_config/parameter_reference#FW_WP_RST_DIST">FW_WP_RST_DIST</a> parameter (default <code>-1</code>, disabled): if a horizontal position reset larger than this distance occurs while flying between two mission waypoints, the vehicle flies directly to the current waypoint instead of rejoining the original line. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27722" target="_blank" rel="noreferrer">PX4-Autopilot#27722</a>)</li><li>Internal combustion engine control gains a feed-forward PI idle-RPM governor, enabled by setting <a href="./../advanced_config/parameter_reference#ICE_IDLE_RPM">ICE_IDLE_RPM</a> above <code>0</code> (disabled by default). New gains <a href="./../advanced_config/parameter_reference#ICE_IDLE_RPM_P">ICE_IDLE_RPM_P</a>, <a href="./../advanced_config/parameter_reference#ICE_IDLE_RPM_I">ICE_IDLE_RPM_I</a>, and feed-forward throttle <a href="./../advanced_config/parameter_reference#ICE_IDLE_THR_FF">ICE_IDLE_THR_FF</a> tune the idle hold. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27650" target="_blank" rel="noreferrer">PX4-Autopilot#27650</a>)</li><li>The performance model now warns when <a href="./../advanced_config/parameter_reference#FW_R_LIM">FW_R_LIM</a> is infeasible because the roll-compensated airspeed range is empty, prompting the user to raise the maximum airspeed. See <a href="./../config_fw/weight_and_altitude_tuning">Weight and Altitude Tuning</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27547" target="_blank" rel="noreferrer">PX4-Autopilot#27547</a>)</li><li>TECS default for the height-rate feed-forward <a href="./../advanced_config/parameter_reference#FW_T_HRATE_FF">FW_T_HRATE_FF</a> increased from <code>0.3</code> to <code>0.5</code>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27218" target="_blank" rel="noreferrer">PX4-Autopilot#27218</a>)</li><li>Catapult/hand <a href="./../flight_modes_fw/takeoff">launch detection</a> now uses total acceleration magnitude instead of only the body-forward component, making detection insensitive to launcher mounting orientation. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26857" target="_blank" rel="noreferrer">PX4-Autopilot#26857</a>)</li></ul><h3 id="rover" tabindex="-1">Rover <a class="header-anchor" href="#rover" aria-label="Permalink to &quot;Rover&quot;">​</a></h3><ul><li>Added a rover build target for the ARK Pi6X (<code>make ark_pi6x_rover</code>), enabling the Ackermann, differential, and mecanum rover modules and the RoboClaw motor driver. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26296" target="_blank" rel="noreferrer">PX4-Autopilot#26296</a>)</li></ul><h3 id="비행선" tabindex="-1">비행선 <a class="header-anchor" href="#비행선" aria-label="Permalink to &quot;비행선&quot;">​</a></h3><ul><li>Added a Generic Airship airframe with two forward thrusters and a cruciform tail (elevators and rudders), alongside the existing Cloudship geometry. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27697" target="_blank" rel="noreferrer">PX4-Autopilot#27697</a>)</li></ul><h2 id="mavlink" tabindex="-1">MAVLink <a class="header-anchor" href="#mavlink" aria-label="Permalink to &quot;MAVLink&quot;">​</a></h2><ul><li>Removed support for deprecated request commands <code>MAV_CMD_REQUEST_AUTOPILOT_CAPABILITIES</code>, <code>MAV_CMD_REQUEST_PROTOCOL_VERSION</code>, <code>MAV_CMD_GET_HOME_POSITION</code>, <code>MAV_CMD_REQUEST_FLIGHT_INFORMATION</code>, <code>MAV_CMD_REQUEST_STORAGE_INFORMATION</code> (Replaced by <code>MAV_CMD_REQUEST_MESSAGE</code>). (<a href="https://github.com/PX4/PX4-Autopilot/pull/27251" target="_blank" rel="noreferrer">PX4-Autopilot#27251: fix(mavlink): Remove deprecated MAV_CMD_REQUEST_AUTOPILOT_CAPABILITIES</a>, <a href="https://github.com/PX4/PX4-Autopilot/pull/27252" target="_blank" rel="noreferrer">PX4-Autopilot#27252: fix(mavlink): Remove legacy mavlink message requestors#27252</a>)</li><li>MAVLink signing is now spec-compliant: signing activates only when a valid key is present on the SD card, <code>SETUP_SIGNING</code> is accepted on any link (not just USB) but rejected while armed, and signing can be disabled with a signed all-zero key. The non-standard <code>MAV_SIGN_CFG</code> parameter was removed and there is zero CPU/bandwidth overhead when signing is inactive. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26894" target="_blank" rel="noreferrer">PX4-Autopilot#26894</a>)</li><li>MAVLink FTP now maps the <code>@MAV_LOG</code> virtual directory (per the MAVLink FTP spec) to the flight-stack log root, so a GCS can browse logs without knowing the on-disk path. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27151" target="_blank" rel="noreferrer">PX4-Autopilot#27151</a>)</li><li>MAVLink FTP adds support for the <code>ListDirectoryWithTime</code> command, returning each file&#39;s last-modification time alongside the listing so a GCS can retrieve log timestamps without downloading the files (clients fall back to plain <code>ListDirectory</code> when unsupported). (<a href="https://github.com/PX4/PX4-Autopilot/pull/27542" target="_blank" rel="noreferrer">PX4-Autopilot#27542</a>)</li><li>Fragmented <code>GPS_RTCM_DATA</code> messages are now reassembled before injection to the GPS receiver, with a compatibility fallback for older QGroundControl builds that omit the final zero-length fragment, fixing RTK correction handling for multi-fragment RTCM streams. See <a href="./../advanced/rtk_gps">RTK GPS</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27084" target="_blank" rel="noreferrer">PX4-Autopilot#27084</a>)</li><li>New <code>ESTIMATOR_SENSOR_FUSION_STATUS</code> MAVLink stream exposes per-sensor intended and active fusion bitmasks to the GCS. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26739" target="_blank" rel="noreferrer">PX4-Autopilot#26739</a>)</li><li>The mission protocol now resends <code>MISSION_COUNT</code> if no <code>MISSION_ACK</code> is received, recovering from a dropped <code>MISSION_COUNT</code> during upload. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26872" target="_blank" rel="noreferrer">PX4-Autopilot#26872</a>)</li><li>The MAVLink development dialect (<code>development.xml</code>) is no longer built into default targets; dedicated <code>mavlink-dev</code> build variants (fmu-v6x, sitl) are provided for prototyping unstable messages. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25834" target="_blank" rel="noreferrer">PX4-Autopilot#25834</a>)</li><li>Added support for the <code>MAV_CMD_DO_SET_GLOBAL_ORIGIN</code> command, letting a GCS set the global origin used to convert local to global position. Enabled in release builds. (<a href="https://github.com/PX4/PX4-Autopilot/pull/24697" target="_blank" rel="noreferrer">PX4-Autopilot#24697</a>, <a href="https://github.com/PX4/PX4-Autopilot/pull/27789" target="_blank" rel="noreferrer">PX4-Autopilot#27789</a>)</li><li>The <code>cellular_status</code> uORB message and MAVLink <code>CELLULAR_STATUS</code> stream gained extended fields for richer modem/link reporting. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27760" target="_blank" rel="noreferrer">PX4-Autopilot#27760</a>)</li></ul><h2 id="ethernet-networking" tabindex="-1">Ethernet &amp; Networking <a class="header-anchor" href="#ethernet-networking" aria-label="Permalink to &quot;Ethernet &amp; Networking&quot;">​</a></h2><ul><li>MAVLink over UDP on NuttX now sets a send timeout on the socket, so a saturated or stalled network link can no longer block the MAVLink sender indefinitely while waiting for IO buffers. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26988" target="_blank" rel="noreferrer">PX4-Autopilot#26988</a>)</li><li>The uXRCE-DDS client no longer stalls under high UDP load. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26161" target="_blank" rel="noreferrer">PX4-Autopilot#26161</a>)</li></ul><h2 id="ros-2" tabindex="-1">ROS 2 <a class="header-anchor" href="#ros-2" aria-label="Permalink to &quot;ROS 2&quot;">​</a></h2><ul><li><a href="./../ros2/px4_ros2_control_interface">External modes</a> can now negotiate their setpoint type with PX4: a mode publishes a <code>SetpointConfig</code> declaring which setpoint it will send (direct actuators, goto, trajectory, rates, attitude, rover, 6-DOF trajectory, thrust/torque, position triplet, etc.) and PX4 replies with a <code>SetpointConfigReply</code> indicating whether the configuration is valid for the current vehicle, along with a configurable setpoint timeout. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27683" target="_blank" rel="noreferrer">PX4-Autopilot#27683</a>)</li></ul><h3 id="uxrce-dds" tabindex="-1">uXRCE-DDS <a class="header-anchor" href="#uxrce-dds" aria-label="Permalink to &quot;uXRCE-DDS&quot;">​</a></h3><ul><li><p><a href="./../middleware/uxrce_dds#version-selection">DDS version selection</a>. Added support for DDS v3, ROS 2 Lyrical Luth and Rolling Ridley (<a href="https://github.com/PX4/PX4-Autopilot/pull/27597" target="_blank" rel="noreferrer">PX4-Autopilot#27597</a>)</p></li><li><p>Topic bridging gained per-topic drain and unlimited-rate options, letting a topic be published as fast as it updates instead of at a fixed interval. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27688" target="_blank" rel="noreferrer">PX4-Autopilot#27688</a>)</p></li><li><p>Added rate limiter to <a href="./../msg_docs/VehicleAttitude"><code>vehicle_attitude</code></a> and <a href="./../msg_docs/VehicleOdometry"><code>vehicle_odometry</code></a> topic publishers. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25792" target="_blank" rel="noreferrer">PX4-Autopilot#25792</a>)</p></li><li><p>New uORB topics bridged. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27681" target="_blank" rel="noreferrer">PX4-Autopilot#27681</a>)</p><table tabindex="0"><thead><tr><th>uORB</th><th>ROS 2</th><th>방향</th><th>Instance</th><th>Max Rate [Hz]</th></tr></thead><tbody><tr><td><code>vtx</code></td><td><code>/fmu/out/vtx</code></td><td>PX4 to ROS 2</td><td><code>0</code></td><td>1</td></tr><tr><td><code>input_rc</code></td><td><code>/fmu/out/input_rc</code></td><td>PX4 to ROS 2</td><td><code>0</code></td><td>10</td></tr></tbody></table></li><li><p><a href="./../middleware/uxrce_dds#dds-topics-yaml">Multi instance publication</a>. Added <code>instance</code> field to the <code>publications</code> section of <code>dds_topics.yaml</code> to control which uORB instance is published to ROS 2. Defaults to instance zero. (<a href="https://github.com/PX4/PX4-Autopilot/pull/22350" target="_blank" rel="noreferrer">PX4-Autopilot#22350</a>)</p></li><li><p>Added support for hardware flow control when using serial communication. <strong>Note:</strong> <a href="https://github.com/eProsima/Micro-XRCE-DDS-Agent/pull/407" target="_blank" rel="noreferrer">Custom Micro XRCE DDS Agent</a> build is required. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26209" target="_blank" rel="noreferrer">PX4-Autopilot#26209</a>)</p></li><li><p>ROS 2 subscriptions can be demuxed into different uORB topic instances. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26305" target="_blank" rel="noreferrer">PX4-Autopilot#26305</a>)</p></li></ul><h3 id="zenoh" tabindex="-1">Zenoh <a class="header-anchor" href="#zenoh" aria-label="Permalink to &quot;Zenoh&quot;">​</a></h3><ul><li>Zenoh publisher options (reliability, priority, congestion control, express) are now configurable, both as common defaults and per-publisher overrides gated by the <code>ZENOH_PUB_OPTION_OVERRIDE</code> build option. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27157" target="_blank" rel="noreferrer">PX4-Autopilot#27157</a>)</li><li>Added a Zenoh build variant (<code>zenoh.px4board</code>) for the ARKV6X flight controller. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25887" target="_blank" rel="noreferrer">PX4-Autopilot#25887</a>)</li><li>Added support for ROS 2 Humble and earlier. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26619" target="_blank" rel="noreferrer">PX4-Autopilot#26619</a>)</li></ul><h2 id="시뮬레이션" tabindex="-1">시뮬레이션 <a class="header-anchor" href="#시뮬레이션" aria-label="Permalink to &quot;시뮬레이션&quot;">​</a></h2><h3 id="sitl" tabindex="-1">SITL <a class="header-anchor" href="#sitl" aria-label="Permalink to &quot;SITL&quot;">​</a></h3><ul><li><a href="./../sim_xplane/">X-Plane SITL</a>: new SITL integration with airframes for the Cessna 172, Bayraktar TB2, EHang 184, Alia-250, and a quad tailsitter. (<a href="https://github.com/PX4/PX4-Autopilot/pull/22493" target="_blank" rel="noreferrer">PX4-Autopilot#22493</a>)</li><li><a href="./../sim_rotorpy/">RotorPy SITL</a>: added support for the RotorPy multirotor simulator, launchable via the standard simulator start scripts. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27116" target="_blank" rel="noreferrer">PX4-Autopilot#27116</a>)</li><li>MAVLink can now be bound to a specific network interface by setting the <code>PX4_NET_INTERFACE</code> environment variable. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26385" target="_blank" rel="noreferrer">PX4-Autopilot#26385</a>)</li><li>The simulated GPS (<code>sensor_gps_sim</code>) now supports failure injection via <code>MAV_CMD_INJECT_FAILURE</code> (<code>FAILURE_UNIT_SENSOR_GPS</code>) with off, stuck, and wrong modes, selectable per receiver. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27396" target="_blank" rel="noreferrer">PX4-Autopilot#27396</a>)</li><li>The simulated airspeed sensor (<code>sensor_airspeed_sim</code>) now supports off, stuck, and wrong failure injection via <code>MAV_CMD_INJECT_FAILURE</code>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27006" target="_blank" rel="noreferrer">PX4-Autopilot#27006</a>)</li></ul><h3 id="gazebo" tabindex="-1">Gazebo <a class="header-anchor" href="#gazebo" aria-label="Permalink to &quot;Gazebo&quot;">​</a></h3><ul><li>Add <a href="./../sim_gazebo_gz/worlds#ridge">ridge world</a> for testing terrain following with 1D lidar. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27600" target="_blank" rel="noreferrer">PX4-Autopilot#27600</a>)</li><li>The <a href="./../sim_gazebo_gz/">gstreamer plugin</a> now supports streaming video from multiple cameras/vehicles simultaneously over UDP (base port plus instance offset); RTMP remains single-stream. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27275" target="_blank" rel="noreferrer">PX4-Autopilot#27275</a>)</li></ul><h3 id="sih" tabindex="-1">SIH <a class="header-anchor" href="#sih" aria-label="Permalink to &quot;SIH&quot;">​</a></h3><ul><li>Add option to set wind velocity (<a href="https://github.com/PX4/PX4-Autopilot/pull/26467" target="_blank" rel="noreferrer">PX4-Autopilot#26467</a>)</li><li>Added a quadratic thrust model and a hexacopter (<code>sihsim_hex</code>) airframe for more realistic multirotor simulation. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26587" target="_blank" rel="noreferrer">PX4-Autopilot#26587</a>)</li><li>Added a propeller aerodynamic model with advance ratio, plus new HIL airframes including a hexacopter (<code>1105_rc_hexa_x_sih</code>). (<a href="https://github.com/PX4/PX4-Autopilot/pull/26720" target="_blank" rel="noreferrer">PX4-Autopilot#26720</a>)</li><li>Added ranging-beacon simulation with configurable measurement noise via <a href="./../advanced_config/parameter_reference#SIH_RNGBC_NOISE">SIH_RNGBC_NOISE</a> (default <code>30</code> m). (<a href="https://github.com/PX4/PX4-Autopilot/pull/26772" target="_blank" rel="noreferrer">PX4-Autopilot#26772</a>)</li><li>The simulator now publishes ESC telemetry (per-motor RPM and temperature) for testing ESC status handling in SITL. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27626" target="_blank" rel="noreferrer">PX4-Autopilot#27626</a>)</li><li>Added a dedicated SIH SITL build target (<code>px4_sitl_sih</code>) that disables the Gazebo bridge/plugins, and taught <code>sitl_multiple_run.sh</code> to accept model and build-target arguments for multi-instance SIH runs. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26672" target="_blank" rel="noreferrer">PX4-Autopilot#26672</a>)</li></ul><h3 id="hil" tabindex="-1">HIL <a class="header-anchor" href="#hil" aria-label="Permalink to &quot;HIL&quot;">​</a></h3><ul><li>Sensor calibration is now disabled while running in hardware-in-the-loop, preventing accidental calibration of simulated sensors. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26942" target="_blank" rel="noreferrer">PX4-Autopilot#26942</a>)</li></ul><h2 id="debug-logging" tabindex="-1">Debug &amp; Logging <a class="header-anchor" href="#debug-logging" aria-label="Permalink to &quot;Debug &amp; Logging&quot;">​</a></h2><h3 id="로깅" tabindex="-1">로깅 <a class="header-anchor" href="#로깅" aria-label="Permalink to &quot;로깅&quot;">​</a></h3><ul><li>Logger: reworked log rotation and cleanup. Log rotation is now on by default, and cleanup runs at log start rather than boot so logs can be downloaded via FTP before being deleted. <ul><li>New <a href="./../advanced_config/parameter_reference#SDLOG_MAX_SIZE">SDLOG_MAX_SIZE</a> (default <code>1024</code> MB) caps the size of a single log file; once reached, the logger closes the current file and starts a new one.</li><li>New <a href="./../advanced_config/parameter_reference#SDLOG_ROTATE">SDLOG_ROTATE</a> (default <code>90</code>) sets the maximum disk usage percentage. Cleanup guarantees <code>(100 - SDLOG_ROTATE)%</code> of the disk stays free at all times, even while writing a new log file. Set <code>0</code> to disable space-based cleanup, <code>100</code> to allow filling the disk completely.</li><li><code>SDLOG_DIRS_MAX</code> is now an orthogonal cap on the number of log directories (default <code>0</code> = disabled), on top of the space-based cleanup driven by <code>SDLOG_ROTATE</code> and <code>SDLOG_MAX_SIZE</code>. SITL defaults to <code>7</code>.</li></ul></li><li>Logger: support for small flash storage (e.g. 128 MB W25N NAND on kakuteh7mini, kakuteh7v2, airbrainh743). Logs can now be written directly to an internal littlefs volume instead of requiring an SD card.</li><li>Logger: topics listed in <code>etc/logging/logger_topics.txt</code> on the SD card are now appended on top of the selected logging profile instead of replacing the entire topic set. Previous behavior (the file overriding all profile topics) is gone; add only the extra topics you want. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27462" target="_blank" rel="noreferrer">PX4-Autopilot#27462</a>)</li><li>Logger: the high-rate sensors logging profile now records <code>sensor_baro</code>, <code>sensor_mag</code>, <code>sensor_gps</code>, <code>sensor_gnss_relative</code>, <code>distance_sensor</code>, <code>sensor_optical_flow</code>, <code>vehicle_air_data</code>, <code>vehicle_magnetometer</code>, <code>vehicle_thrust_setpoint</code>, and <code>estimator_aid_src_baro_hgt</code> at 100 Hz. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26922" target="_blank" rel="noreferrer">PX4-Autopilot#26922</a>)</li><li><a href="./../debug/asset_tracking">Asset Tracking</a>: Automatic tracking and logging of external device information including vendor name, firmware and hardware version, serial numbers. Currently supports DroneCAN devices. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25617" target="_blank" rel="noreferrer">PX4-Autopilot#25617</a>)</li></ul><h3 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;Storage&quot;">​</a></h3><ul><li>MTD/storage: added NOR flash support (with bulk erase) to the <code>mtd</code> subsystem and manifest, allowing NOR flash to be used as a storage backend (e.g. for parameters and littlefs volumes) on boards that provide it, such as FMU-v6s.</li><li>New <code>mklittlefs</code> systemcmd for reformatting a littlefs volume from the NSH console, analogous to <code>mkfatfs</code> for FAT filesystems.</li></ul><h2 id="infrastructure" tabindex="-1">Infrastructure <a class="header-anchor" href="#infrastructure" aria-label="Permalink to &quot;Infrastructure&quot;">​</a></h2><ul><li>SPDX 2.3 SBOM (software bill of materials) generation is now integrated into the firmware build via <code>cmake/sbom.cmake</code>. SBOMs are produced automatically as part of the build and can be disabled by setting the <code>PX4_SBOM_DISABLE=1</code> environment variable. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26731" target="_blank" rel="noreferrer">PX4-Autopilot#26731</a>)</li><li>New <code>px4bench</code> <a href="./../test_and_ci/bench_testing">hardware bench testing</a> suite (<code>Tools/bench_test/</code>) qualifies a firmware build on a real NuttX board over USB: it flashes and verifies the firmware identity, then runs boot, communication, storage, parameter-persistence, and serial-loopback checks, plus an optional SIH auto mission flown on the FMU itself, writing machine-readable reports with full firmware traceability. Adds <code>bench</code> test build variants (e.g. FMU-v6XRT). (<a href="https://github.com/PX4/PX4-Autopilot/pull/27823" target="_blank" rel="noreferrer">PX4-Autopilot#27823</a>)</li><li>SITL can now be built with <a href="./../test_and_ci/sanitizers">AddressSanitizer and ThreadSanitizer</a> to catch memory errors and data races; a series of data races found this way in MAVLink and the lockstep scheduler were fixed. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27606" target="_blank" rel="noreferrer">PX4-Autopilot#27606</a>)</li><li>Firmware upload now works from WSL2. When building inside WSL2, the uploader detects and uses the Windows Python interpreter (<code>python.exe</code>) to reach <code>COM&lt;N&gt;</code> serial ports that WSL2 cannot expose directly. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27674" target="_blank" rel="noreferrer">PX4-Autopilot#27674</a>)</li><li>SITL Debian packages now declare their runtime dependencies (including Gazebo Harmonic) via <code>.deb</code> <code>Depends</code>, so <code>apt</code> resolves everything needed to run the simulator. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27162" target="_blank" rel="noreferrer">PX4-Autopilot#27162</a>, <a href="https://github.com/PX4/PX4-Autopilot/pull/27178" target="_blank" rel="noreferrer">PX4-Autopilot#27178</a>)</li><li>macOS development setup reworked: the toolchain installs via inline Homebrew dependencies in <code>Tools/setup/macos.sh</code> (the <code>px4-dev</code> meta-formula is deprecated), Python dependencies can install into a virtual environment, and Gazebo SITL works out of the box with Homebrew 4.5+. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27127" target="_blank" rel="noreferrer">PX4-Autopilot#27127</a>, <a href="https://github.com/PX4/PX4-Autopilot/pull/27148" target="_blank" rel="noreferrer">PX4-Autopilot#27148</a>, <a href="https://github.com/PX4/PX4-Autopilot/pull/26702" target="_blank" rel="noreferrer">PX4-Autopilot#26702</a>)</li><li>PX4-OpticalFlow is now a git submodule instead of a build-time download, making SITL builds reproducible and offline-friendly. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27184" target="_blank" rel="noreferrer">PX4-Autopilot#27184</a>)</li><li>New <code>make format_changed</code> target formats only files that differ from <code>HEAD</code> (via astyle), which is much faster than <code>make format</code> scanning the whole tree. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27122" target="_blank" rel="noreferrer">PX4-Autopilot#27122</a>)</li><li>Added DroneCAN sensor latency calibration scripts under <code>Tools/dronecan_calibration/</code> (<code>range_sensor_latency.py</code>, <code>flow_sensor_latency.py</code>) that cross-correlate CAN sensor signals against the FC&#39;s directly-connected IMU in flight logs to estimate CAN transport/pipeline delay.</li></ul>',67))])}}});export{P as __pageData,A as default};
